function summarizeWindow(events, nowMs, windowMs, cap) {
  // Pass 1: deduplicate raw events by non-empty string id, keeping the FIRST
  // occurrence in input array order. Events without a non-empty string id
  // are never deduplicated and all flow through.
  const seen = new Set();
  const deduped = [];
  for (const ev of events) {
    if (ev && typeof ev.id === 'string' && ev.id !== '') {
      if (seen.has(ev.id)) continue;
      seen.add(ev.id);
    }
    deduped.push(ev);
  }

  // Pass 2: apply the qualification filter over the deduplicated stream.
  const windowStart = nowMs - windowMs;
  const qualifying = [];
  for (const ev of deduped) {
    if (!ev) continue;
    if (typeof ev.ts !== 'number' || !Number.isFinite(ev.ts)) continue;
    if (!(ev.ts >= windowStart && ev.ts <= nowMs)) continue;
    if (ev.provider !== 'opencode-go') continue;
    if (ev.error) continue; // rejected/unbilled rows are ignored
    if (typeof ev.model !== 'string') continue;
    if (ev.model.toLowerCase().endsWith('-free')) continue; // free pool never burns quota
    qualifying.push(ev);
  }

  const used = qualifying.length;
  const remaining = Math.max(0, cap - used);
  const pct = Math.round((used / cap) * 1000) / 10;
  const overCap = used > cap;

  let oldestExpiresAt = null;
  if (used > 0) {
    let minTs = Infinity;
    for (const ev of qualifying) {
      if (ev.ts < minTs) minTs = ev.ts;
    }
    oldestExpiresAt = minTs + windowMs;
  }

  const counts = Object.create(null);
  for (const ev of qualifying) {
    let name = ev.model;
    if (name.startsWith('opencode-go/')) name = name.slice('opencode-go/'.length);
    name = name.toLowerCase();
    counts[name] = (counts[name] || 0) + 1;
  }
  const byModel = {};
  for (const key of Object.keys(counts).sort()) {
    byModel[key] = counts[key];
  }

  return { used, remaining, pct, overCap, oldestExpiresAt, byModel };
}
